from typing import List

class Solution:
    def lengthOfLIS(self, nums: List[int], k: int) -> int:
        def dfs(i):
            res = 1
            for j in range(i + 1, len(nums)):
                if nums[j] <= nums[i]:
                    continue
                if nums[j] - nums[i] <= k:
                    res = max(res, 1 + dfs(j))
            return res

        res = 0
        for i in range(len(nums)):
            res = max(res, dfs(i))
        return res

from typing import List

class Solution:
    def lengthOfLIS(self, nums: List[int], k: int) -> int:
        n, res = len(nums), 0
        dp = [1] * n
        for i in range(n):
            for j in range(i):
                if nums[j] >= nums[i]:
                    continue
                if nums[i] - nums[j] <= k:
                    dp[i] = max(dp[i], 1 + dp[j])
            res = max(res, dp[i])
        return res
